    internal SmartConfig()
    {
        var c = MelonPreferences.CreateCategory(CategoryName);

        ConfigurationVersion = c.CreateEntry("Configuration Version", CurrentConfigurationVersion,
            description: "Internal configuration migration version. Do not edit manually.", is_hidden: true);
        Enabled = c.CreateEntry("Enabled", true, description: "Master Smart Strategy switch; press F9 in game to toggle it.");
        EndgameModeEnabled = c.CreateEntry("Endgame Mode Enabled", false, description: "Master endgame switch. Enables permanent free multipliers, permanent timed craftables, and 500x effects while removing short-window routing guards; disabling it restores normal strategy.");
        ToggleKey = c.CreateEntry("Toggle Key", "F9", description: "Hotkey for the Smart Strategy master switch.");
        EmergencyStopKey = c.CreateEntry("Emergency Stop Key", "F10", description: "Immediately stops every automated Smart Strategy action; use the master toggle to recover.");
        MaterialTravelToggleKey = c.CreateEntry("Material Travel Toggle Key", "F6", description: "Toggles only automated material travel; event crafting may continue.");
        StatusKey = c.CreateEntry("Status Key", "F7", description: "Writes the current event, material target, and crafting capacity to the log.");
        CheckIntervalSeconds = c.CreateEntry("Check Interval Seconds", 0.5f, description: "Strategy evaluation interval, clamped to at least 0.2 seconds.");
        StableRunnerSeconds = c.CreateEntry("Stable Runner Seconds", 2f, description: "Settling time after returning to Runner or Rage mode.");
        DebugLogging = c.CreateEntry("Debug Logging", false, description: "Writes detailed planning and deferral diagnostics.");
        GiantRapidAttackEnabled = c.CreateEntry("Giant Rapid Attack Enabled", true, description: "Captures the native BMAttack parameter after entering Giant battle, calls the battle interface rapidly, and stops immediately after leaving battle.");
        GiantRapidAttackIntervalSeconds = c.CreateEntry("Giant Rapid Attack Interval Seconds", 0.03f, description: "Giant melee attack request interval, clamped to at least 0.01 seconds.");
        AutomaticCombatEnabled = c.CreateEntry("Automatic Combat Enabled", true, description: "Coordinates automatic jumping, regular Boost, bow attacks, and Wind Dash; press F4 in game to toggle it.");
        CombatToggleKey = c.CreateEntry("Combat Toggle Key", "F4", description: "Toggles this mod's movement and smart combat. F8 is reserved by Auto Daily Roulette; other mod switches are never changed.");
        AutomaticJumpEnabled = c.CreateEntry("Automatic Jump Enabled", true, description: "Controls jumps during normal running from unmagnetized boxes, complete coin or gemstone patterns, and Giant priority.");
        AutomaticJumpRetrySeconds = c.CreateEntry("Automatic Jump Retry Seconds", 0.08f, description: "Retry interval after a short-jump input is rejected while airborne; minimum 0.04 seconds.");
        AutomaticJumpMaximumHoldSeconds = c.CreateEntry("Automatic Jump Maximum Hold Seconds", 0.3f, description: "Maximum jump-input hold. Solved from the highest live row, never exceeds native jumpTime, and uses temporary jumpForce scaling only for exceptionally high patterns.");
        if (Math.Abs(AutomaticJumpMaximumHoldSeconds.Value - 0.5f) < 0.001f)
            AutomaticJumpMaximumHoldSeconds.Value = 0.3f;
        AutomaticJumpMaximumForceMultiplier = c.CreateEntry("Automatic Jump Maximum Force Multiplier", 1.75f, description: "Maximum temporary jump-force multiplier for exceptionally high coin patterns. Restored immediately after the jump; boxes always use 1.0x.");
        AutomaticBoostEnabled = c.CreateEntry("Automatic Boost Enabled", true, description: "Automatically activates only the currently selected regular Boost; Wind Dash is selected from enemy positions and expected value.");
        AutomaticBoostActivationDelaySeconds = c.CreateEntry("Automatic Boost Activation Delay Seconds", 0.2f, description: "Settling delay after regular Boost cooldown completes.");
        CombatDecisionIntervalSeconds = c.CreateEntry("Combat Decision Interval Seconds", 0.10f, description: "Interval for rescoring active enemy positions and attack modes; minimum 0.05 seconds.");
        BowAttackRequestIntervalSeconds = c.CreateEntry("Bow Attack Request Interval Seconds", 0.10f, description: "Bow request interval while a hittable target exists; the game still owns the native bow cooldown.");
        WindDashActivationViewportLead = c.CreateEntry("Wind Dash Activation Viewport Lead", 0.38f, description: "Maximum viewport-width lead at which enemies may trigger Wind Dash; the live vertical collision range is also checked.");
        WindDashMinimumTargets = c.CreateEntry("Wind Dash Minimum Targets", 2, description: "Minimum targets required to spend a Wind Dash cooldown in ordinary value mode. One bow-immune quest or material target is sufficient.");
        WindDashMinimumGainPercent = c.CreateEntry("Wind Dash Minimum Gain Percent", 15f, description: "Required Wind Dash score advantage over bow attacks for the same nearby group in ordinary value mode.");
        CombatModeMinimumHoldSeconds = c.CreateEntry("Combat Mode Minimum Hold Seconds", 0.75f, description: "Minimum attack-mode hold without a hard quest constraint, preventing oscillation near decision boundaries.");
        RageDuringHordeEventEnabled = c.CreateEntry("Rage During Horde Event Enabled", true, description: "Activates Rage in place when a Horde starts and natural cooldown is ready; the latest travel plan resumes after the event.");
        HordeRagePillEnabled = c.CreateEntry("Horde Rage Pill Enabled", false, description: "Legacy setting. Since 0.4.26, Horde events never use Rage Pills and activate Rage only after natural cooldown.");
        HordeRagePillCooldownThresholdSeconds = c.CreateEntry("Horde Rage Pill Cooldown Threshold Seconds", 10f, description: "Legacy setting; Horde Rage Pill strategy is retired.");

        MinimumSoulsMultiplier = c.CreateEntry("Minimum Souls Multiplier", 10f, description: "Minimum random Souls multiplier that enters burst strategy.");
        PermanentFreeMultipliersEnabled = c.CreateEntry("Permanent Free Multipliers Enabled", true, description: "Keeps all unlocked timed client rewards active: Souls, CpS, coin value, equipment bonus, Gemstone Rush, and Frenzy. Horde and one-shot rewards are excluded.");
        PermanentFreeSoulsBonusEnabled = c.CreateEntry("Permanent Free Souls Bonus Enabled", true, description: "Keeps the free Gold Souls event active in endgame. Reactivates only after the native effect ends, never changes paid multipliers, and does not stack duration repeatedly.");
        PermanentTimedCraftableEffectsEnabled = c.CreateEntry("Permanent Timed Craftable Effects Enabled", true, description: "Activates and freezes every unlocked timed craftable without calling Craft or consuming materials. One-shot pills, keys, and eggs are excluded.");
