        ControlRageActivation = c.CreateEntry("Control Rage Activation", true, description: "Allows this mod to activate Rage directly during eligible Souls events.");
        UseRageWheneverReady = c.CreateEntry("Use Rage Whenever Ready", true, description: "Activates Rage whenever natural cooldown completes on an active farming map. Cross-map travel opens the Portal first; Souls events may still chain with pills.");
        MinimumSecondsToStartRage = c.CreateEntry("Minimum Seconds To Start Rage", 8f, description: "Minimum Souls-event time remaining before starting a new Rage window.");
        RagePillEnabled = c.CreateEntry("Rage Pill Enabled", true, description: "Crafts a pill to start Rage when cooldown remains during a Souls event, then pre-clears cooldown during Rage for another window in the same event.");
        MinimumSecondsForAnotherRage = c.CreateEntry("Minimum Seconds For Another Rage", 14f, description: "Minimum event time remaining before spending a pill on another Rage window.");
        MaximumRagePillsPerEvent = c.CreateEntry("Maximum Rage Pills Per Event", 2, description: "Hard Rage Pill limit per Souls event; the default covers one start and one extension.");
        SecondRagePillMinimumSoulsMultiplier = c.CreateEntry("Second Rage Pill Minimum Souls Multiplier", 30f, description: "Minimum multiplier for a second pill in the same Souls event; the first still uses Minimum Souls Multiplier.");
        RagePillReserveUses = c.CreateEntry("Rage Pill Reserve Uses", 1, description: "Craftable uses reserved for a second event pill and quest pills. Only the first Souls-event pill may borrow the final reserve.");
        RagePillRefillTriggerUses = c.CreateEntry("Rage Pill Refill Trigger Uses", 0, description: "Applies only when dedicated pill restocking is enabled; zero restocks only when no additional pill can be crafted.");
        DedicatedRagePillMaterialFarming = c.CreateEntry("Dedicated Rage Pill Material Farming", false, description: "Maintains global Rage Pill stock when enabled. Rage-kill quests can still compare exactly one pill's supply time against natural cooldown and restock only when net savings pass the threshold.");
        ShardsNecklaceEnabled = c.CreateEntry("Shards Necklace Enabled", true, description: "Maintains Shards Necklace during a Souls event on a map with Giants.");
        ShardsNecklaceReserveUses = c.CreateEntry("Shards Necklace Reserve Uses", 1, description: "Craftable Shards Necklace uses retained after crafting.");
        SoulsCompassEnabled = c.CreateEntry("Souls Compass Enabled", true, description: "Maintains Souls Compass coverage during Souls events.");
        SoulsCompassReserveUses = c.CreateEntry("Souls Compass Reserve Uses", 1, description: "Craftable Souls Compass uses retained after crafting.");
        CriticalSwordEnabled = c.CreateEntry("Critical Sword Enabled", true, description: "Maintains Critical Sword during high-multiplier Souls events on maps with Giants.");
        CriticalSwordMinimumMultiplier = c.CreateEntry("Critical Sword Minimum Multiplier", 20f, description: "Minimum Souls-event multiplier for Critical Sword.");
        CriticalSwordReserveUses = c.CreateEntry("Critical Sword Reserve Uses", 0, description: "Craftable Critical Sword uses retained after crafting.");
        SoulsSpyglassEnabled = c.CreateEntry("Souls Spyglass Enabled", true, description: "Maintains long Souls Spyglass coverage during Souls events and before Chest Hunt.");
        SoulsSpyglassRefreshMinutes = c.CreateEntry("Souls Spyglass Refresh Minutes", 30f, description: "Refreshes Souls Spyglass during a Souls-value window only below this remaining duration.");
        SoulsSpyglassReserveUses = c.CreateEntry("Souls Spyglass Reserve Uses", 0, description: "Craftable Souls Spyglass uses retained after crafting.");
        BunnyPawEnabled = c.CreateEntry("Bunny Paw Enabled", true, description: "Normal mode: use Bunny Paw while searching for Souls events, except during a tracked Coins From Random Box objective. Endgame permanent effects ignore this normal-mode switch.");
        DeathBringerEnabled = c.CreateEntry("Death Bringer Enabled", true, description: "Normal mode: use Death Bringer for unlocked Giants on the current map while ordinary sword combat is active. Endgame permanent effects ignore this normal-mode switch.");
        CpsSpyglassEnabled = c.CreateEntry("CPS Spyglass Enabled", true, description: "Normal mode: use CPS Spyglass during a live CPS or coin-value multiplier window. Endgame permanent effects ignore this normal-mode switch.");
